from fastapi import FastAPI
from fastapi.staticfiles import StaticFiles
from fastapi.responses import FileResponse
from sqlalchemy import create_engine, Column, Integer, String
from sqlalchemy.orm import declarative_base, sessionmaker
import os

DATABASE_URL = os.getenv("DATABASE_URL", "postgresql://hanzi_user:hanzi_password@localhost:5432/hanzi_db")

engine = create_engine(DATABASE_URL)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()

class Character(Base):
    __tablename__ = "characters"
    id = Column(Integer, primary_key=True, index=True)
    hanzi = Column(String, unique=True, index=True)
    pinyin = Column(String)
    meaning = Column(String)
    gifs = Column(String) 
    image_url = Column(String)
    audio_url = Column(String) # <--- Добавили колонку для аудио
    context_hint = Column(String)

Base.metadata.create_all(bind=engine)

app = FastAPI()

