@app.on_event("startup")
def seed_db():
    db = SessionLocal()
    if db.query(Character).count() == 0:
        for item in INITIAL_DATA:
            char = Character(**item)
            db.add(char)
        db.commit()
    db.close()

@app.get("/api/words")
def get_words():
    db = SessionLocal()
    words = db.query(Character).order_by(Character.id).all()
    db.close()
    
    # Преобразуем строку gifs в массив для фронтенда
    result = []
    for w in words:
        item = {c.name: getattr(w, c.name) for c in w.__table__.columns}
        item["gifs"] = item["gifs"].split(",") if item["gifs"] else []
        result.append(item)
        
    return result

app.mount("/static", StaticFiles(directory="static"), name="static")

@app.get("/")
def serve_spa():
    return FileResponse("static/index.html")